STATION_HTML = r"""<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chess Station</title><style>:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif;background:#11100e;color:#f3ead9}*{box-sizing:border-box}body{margin:0}.shell{max-width:1000px;margin:auto;padding:32px}h1{font:600 clamp(2.5rem,8vw,5rem) Georgia,serif;margin:.2em 0}.lead{color:#baaf9d;max-width:680px}.card{background:#1c1915;border:1px solid #3b342b;border-radius:18px;padding:22px;margin-top:20px}.row{display:flex;gap:12px;flex-wrap:wrap}input,button{font:inherit;padding:13px 16px;border-radius:9px;border:1px solid #554a3d}input{flex:1;min-width:280px;background:#12100e;color:#fff}button{background:#d4aa6d;color:#17120d;font-weight:800;cursor:pointer}.qr-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:20px}.seat{text-align:center;background:#f7f1e6;color:#1d1812;border-radius:16px;padding:18px}.seat img{width:min(100%,330px);aspect-ratio:1}.seat h2{font:600 2rem Georgia,serif;margin:.2em}.status{font-family:ui-monospace,monospace;color:#d8c6ac}@media(max-width:700px){.qr-grid{grid-template-columns:1fr}.shell{padding:18px}}</style></head><body><main class="shell"><small>RELAY CHESS STATION</small><h1>Scan. Sit. Play.</h1><p class="lead">Prepare the standard board and capture tray once. Create a game, then White and Black scan their own code. The gantry starts automatically when both players join and remains connected until the game finishes. There is no chess clock or idle timeout.</p><section class="card"><div class="row"><input id="confirmation" value="STATION BOARD AND CHUTES READY" aria-label="Safety confirmation"><button id="create">Create game</button><button id="stop">Stop</button></div><p id="status" class="status">No station game.</p><div id="codes" class="qr-grid" hidden><article class="seat"><h2>White</h2><img id="whiteQr" alt="White player QR code"><p id="whiteState">Waiting to scan</p></article><article class="seat"><h2>Black</h2><img id="blackQr" alt="Black player QR code"><p id="blackState">Waiting to scan</p></article></div></section><section id="recovery" class="card" hidden><h2>Physical recovery</h2><p>Inspect the board and pending move. Type STATION PHYSICAL STATE VERIFIED, then choose whether the move completed.</p><div class="row"><input id="recoveryText" placeholder="STATION PHYSICAL STATE VERIFIED"><button id="apply">Move completed</button><button id="discard">Move did not happen</button></div></section></main><script>const $=id=>document.getElementById(id);async function api(path,options={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const j=await r.json();if(!r.ok||j.ok===false)throw new Error(j.error||'Request failed');return j.result||j}function render(s){$('status').textContent=s.error?`FAILED: ${s.error}`:`${s.state||'idle'}${s.result?' · '+s.result:''}`;$('recovery').hidden=!(s.state==='failed'&&s.pending_uci);if(s.game_id){$('codes').hidden=false;$('whiteQr').src='/api/station/qr?seat=white&t='+Date.now();$('blackQr').src='/api/station/qr?seat=black&t='+Date.now();$('whiteState').textContent=s.joined.white?'Joined':'Waiting to scan';$('blackState').textContent=s.joined.black?'Joined':'Waiting to scan'}else $('codes').hidden=true}async function refresh(){try{render(await api('/api/station/status'))}catch(e){$('status').textContent=e.message}}$('create').onclick=async()=>{try{render(await api('/api/station/create',{method:'POST',body:JSON.stringify({confirmation:$('confirmation').value})}))}catch(e){$('status').textContent=e.message}};$('stop').onclick=async()=>{try{render(await api('/api/station/stop',{method:'POST',body:'{}'}))}catch(e){$('status').textContent=e.message}};for(const [id,action] of [['apply','apply'],['discard','discard']])$(id).onclick=async()=>{try{render(await api('/api/station/reconcile/'+action,{method:'POST',body:JSON.stringify({confirmation:$('recoveryText').value})}))}catch(e){$('status').textContent=e.message}};setInterval(refresh,1000);refresh()</script></body></html>"""

STATION_PLAYER_HTML = r"""<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><title>Play Chess</title><style>:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif;background:#0e0d0b;color:#f4ecdd}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center}.app{width:min(100vw,620px);padding:14px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.board{display:grid;grid-template-columns:repeat(8,1fr);width:100%;aspect-ratio:1;border:6px solid #30291f;border-radius:8px;overflow:hidden}.sq{position:relative;border:0;border-radius:0;padding:0;font-size:clamp(28px,9vw,58px);display:grid;place-items:center;color:#111;text-shadow:0 1px #fff8}.light{background:#e8d8bb}.dark{background:#a57a54}.sq.selected{box-shadow:inset 0 0 0 5px #ffd25a}.sq.target::after{content:'';position:absolute;width:28%;aspect-ratio:1;border-radius:50%;background:#2d8f67aa}.status{min-height:48px;padding:12px 2px;color:#c9bda9}.actions{display:flex;gap:10px}.actions button{flex:1;padding:14px;border-radius:9px;border:1px solid #514535;background:#211d17;color:#f4ecdd;font-weight:700}.error{color:#ff7d88}</style></head><body><main class="app"><header class="top"><strong id="seat">Joining…</strong><span id="turn"></span></header><div id="board" class="board"></div><p id="status" class="status">Connecting to station…</p><div class="actions"><button id="resign">Resign</button></div></main><script>let token=location.hash.slice(1),state=null,selected=null,busy=false;const symbols={P:'♙',N:'♘',B:'♗',R:'♖',Q:'♕',K:'♔',p:'♟',n:'♞',b:'♝',r:'♜',q:'♛',k:'♚','.':''};if(token)sessionStorage.setItem('station-seat-token',token);else token=sessionStorage.getItem('station-seat-token')||'';history.replaceState(null,'',location.pathname);async function api(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,...body})});const j=await r.json();if(!r.ok||j.ok===false)throw new Error(j.error||'Request failed');return j.result}function canonical(display){const row=Math.floor(display/8),col=display%8;return state.seat==='white'?(7-row)*8+col:row*8+(7-col)}function name(index){return'abcdefgh'[index%8]+(Math.floor(index/8)+1)}function draw(){const root=document.getElementById('board');root.innerHTML='';const flat=(state.rows||[]).slice().reverse().join('');for(let i=0;i<64;i++){const c=canonical(i),square=name(c),piece=flat[c]||'.',button=document.createElement('button');button.className='sq '+(((c%8+Math.floor(c/8))%2)?'dark':'light');button.textContent=symbols[piece]||'';button.setAttribute('aria-label',square);if(selected===square)button.classList.add('selected');if(selected&&(state.legal_moves||[]).some(m=>m.slice(0,2)===selected&&m.slice(2,4)===square))button.classList.add('target');button.onclick=()=>choose(square);root.appendChild(button)}}async function choose(square){if(!state.your_turn||busy)return;if(!selected){if((state.legal_moves||[]).some(m=>m.startsWith(square)))selected=square;draw();return}let candidates=(state.legal_moves||[]).filter(m=>m.startsWith(selected+square));if(!candidates.length){selected=null;return choose(square)}let move=candidates[0];if(candidates.length>1){const choice=(prompt('Promote to q, r, b, or n','q')||'q').toLowerCase();move=candidates.find(m=>m.endsWith(choice))||candidates[0]}busy=true;try{state=await api('/api/station/move',{uci:move});selected=null;render()}catch(e){showError(e)}finally{busy=false}}function showError(e){document.getElementById('status').textContent=e.message;document.getElementById('status').className='status error'}function render(){document.getElementById('seat').textContent=`${state.seat.toUpperCase()} · ${state.game_id}`;document.getElementById('turn').textContent=state.result?state.result:`${state.turn} to move`;document.getElementById('status').className='status';document.getElementById('status').textContent=state.error||({waiting_players:'Waiting for the other player to scan.',homing:'Both players joined. Homing the gantry…',playing:state.your_turn?'Your move':'Opponent is moving.',executing:'Gantry is mirroring the move…',finished:`Game finished · ${state.result}`,failed:'Station needs operator attention.',stopped:'Game stopped.'}[state.state]||state.state);draw()}async function poll(){if(busy)return;try{state=await api(state?'/api/station/state':'/api/station/join',{});render()}catch(e){showError(e)}}document.getElementById('resign').onclick=async()=>{if(confirm('Resign this game?')){state=await api('/api/station/resign',{});render()}};setInterval(poll,650);poll()</script></body></html>"""
